import * as THREE from './src/Three.js';

const camera = new THREE.PerspectiveCamera( 40, 1.5, 1, 10000 );
camera.position.set( 20, 20, 20 );
camera.up.set( 1, 0, 0 );

const serialized = JSON.stringify( camera );
const jsonCameraObj = JSON.parse( serialized );
const deserializedCamera = new THREE.ObjectLoader().parse( jsonCameraObj );

console.log( 'up =', deserializedCamera.up );
if ( deserializedCamera.up.x !== 1 || deserializedCamera.up.y !== 0 || deserializedCamera.up.z !== 0 ) {
	throw new Error( 'FAIL: up vector not restored' );
}

// default up still works
const cam2 = new THREE.PerspectiveCamera();
const cam3 = new THREE.ObjectLoader().parse( JSON.parse( JSON.stringify( cam2 ) ) );
console.log( 'default up =', cam3.up );
if ( cam3.up.x !== 0 || cam3.up.y !== 1 || cam3.up.z !== 0 ) {
	throw new Error( 'FAIL: default up vector broken' );
}

// object hierarchy sanity check
const scene = new THREE.Scene();
const mesh = new THREE.Mesh( new THREE.BoxGeometry( 1, 1, 1 ) );
mesh.position.set( 1, 2, 3 );
camera.position.set( 0, 0, 0 );
scene.add( mesh, camera );
const sceneOut = new THREE.ObjectLoader().parse( JSON.parse( JSON.stringify( scene ) ) );
const meshOut = sceneOut.children.find( c => c.isMesh );
if ( meshOut.position.z !== 3 ) throw new Error( 'FAIL: transform round-trip broken' );
console.log( 'ALL OK' );

